-- Better Auth 1.7.25, generated by getMigrations. The proof-token digest check is app-specific.
CREATE TABLE "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null);
CREATE TABLE "session" ("id" text not null primary key, "expiresAt" date not null,
  "token" text not null unique CHECK (length(token) = 64 AND token NOT GLOB '*[^a-f0-9]*'),
  "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text,
  "userId" text not null references "user" ("id") on delete cascade);
CREATE TABLE "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);
CREATE TABLE "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);
CREATE INDEX "session_userId_idx" ON "session" ("userId");
CREATE INDEX "account_userId_idx" ON "account" ("userId");
CREATE INDEX "verification_identifier_idx" ON "verification" ("identifier");

CREATE TABLE championship_member_emails (
  user_id TEXT PRIMARY KEY REFERENCES championship_memberships(user_id),
  email TEXT NOT NULL UNIQUE CHECK (email = lower(trim(email)))
) STRICT;

CREATE TABLE championship_invite_requests (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE,
  invited_by TEXT NOT NULL REFERENCES championship_memberships(user_id),
  invited_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
) STRICT;

CREATE TRIGGER championship_invite_creates_member
AFTER INSERT ON championship_invite_requests
BEGIN
  INSERT INTO championship_memberships VALUES (new.id,'member',1);
  INSERT INTO championship_member_emails VALUES (new.id,new.email);
END;

CREATE TABLE championship_login_limits (
  bucket TEXT NOT NULL,
  window INTEGER NOT NULL,
  count INTEGER NOT NULL,
  PRIMARY KEY (bucket,window)
) STRICT;
CREATE INDEX championship_login_limits_window ON championship_login_limits(window);
